def sort_ascending(arr):
    # Iterate through list
    for i in range(len(arr)):
        # Iterate through remaining values
        for j in range(i + 1, len(arr)):
            # Swap two values if first is greater
            if arr[i] > arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
    return arr

