def to_pig_latin(sentence):
    result = ""
    words = sentence.split()
    for word in words:
        # Check if the word starts with a vowel
        if word[0] in "aeiou":
            result += word + "way "
        # If not, move the first letter to the end and add 'ay'
        else:
            result += word[1:] + word[0] + "ay "
    return result

print(to_pig_latin("This is a sentence"))

